var pe2 = escapeHtml;
var hqOrigin = "https://yolo-county-veterans-hq.smartzgraphics.workers.dev";
function submissionPage(url, { error = "", received = false, organizations = [] } = {}) {
  const kind = ["profile", "event", "claim", "other"].includes(url.searchParams.get("kind")) ? url.searchParams.get("kind") : "profile", selected = url.searchParams.get("org") || "";
  return shell("Organization submission desk | Yolo Solano Veterans", "Suggest public profile corrections, share an event or request organization stewardship.", `<section class="wrap workspace-page"><span class="eyebrow">FOR THE ORGANIZATIONS THAT SERVE</span><h1>Your local knowledge.<br><em>A stronger community.</em></h1><p class="intro">Help keep organization information current and bring more people together.</p>${received ? '<div class="preview-banner" role="status"><strong>Received for review.</strong><span>Your submission is saved in the private review queue. It is not published yet. No email confirmation is sent.</span></div>' : error ? `<div class="preview-banner" role="alert"><strong>Submission not saved.</strong><span>${pe2(error)}</span></div>` : ""}<div class="profile-grid"><section class="panel"><h2>Share an update</h2><p>Already designated as a representative? <a href="${hqOrigin}/organization">Sign in to your organization editor →</a></p><p>Use this desk for public organization information. We check the source and handle clear updates before publication. Sign-in is not required to suggest an update.</p><form class="edit-form" method="post" action="/submit"><label>What would you like to do?<select name="kind">${[["profile", "Correct a profile"], ["event", "Propose an event"], ["claim", "Request organization stewardship"], ["other", "Add an organization / other update"]].map(([id, label]) => `<option value="${id}" ${id === kind ? "selected" : ""}>${label}</option>`).join("")}</select></label><label>Organization<select name="org_id"><option value="">New organization / not listed</option>${organizations.map((r) => `<option value="${r.id}" ${r.id === selected ? "selected" : ""}>${pe2(r.verified_name)}</option>`).join("")}</select></label><label>Update title<input name="title" maxlength="180" required placeholder="New meeting time, event title, or organization name"></label><label>Public details<textarea name="details" maxlength="6000" rows="7" required placeholder="For events, include date, time, public venue, organizer, audience and registration details. Use general organization contact channels only; do not include individual contact details or roster links."></textarea></label><label>Official source or public flyer link (optional)<input name="source_url" type="url" maxlength="2000" placeholder="https://"></label><div class="two-up"><label>Your name (private)<input name="sender_name" maxlength="120" autocomplete="name" required></label><label>Reply email (private)<input name="sender_email" type="email" maxlength="254" autocomplete="email" required></label></div><div class="bot-field" aria-hidden="true"><label>Leave this blank<input name="website_check" tabindex="-1" autocomplete="off"></label></div><label class="check"><input type="checkbox" name="privacy" value="yes" required> I am submitting public organization information, with permission to share it. I have not included veteran case details, medical information, discharge papers or private membership lists.</label><p class="small-note">Your name and email stay in the private review queue for follow-up. Proposed public details may be published after review. Do not upload private files through a link. This desk is not monitored for urgent help.</p><button class="button">Submit for review →</button></form></section><aside><section class="panel"><h2>What happens next</h2><ol class="steps"><li><strong>We review the source.</strong><p>Published facts are checked and unclear details are held for follow-up.</p></li><li><strong>We verify stewardship.</strong><p>Requests to manage a profile are checked through an independent organization contact. Submission alone does not grant access.</p></li><li><strong>A reviewed update goes live.</strong><p>Events and corrections have a separate publication step.</p></li></ol></section><section class="panel"><h2>Project coordination</h2><p>Tasks, submissions and shared projects live in the private headquarters. Designated representatives can manage their assigned organization pages after Aaron or Sterling approves their access.</p><a href="${hqOrigin}">Open headquarters ↗</a></section></aside></div></section>`, { path: "/for-organizations" });
}

